begin;

create table public."Dim_Labor" (
  "Id_Lab" bigint generated by default as identity primary key,
  "Lab_SCIRE" character varying not null,
  "Id_Lab_Fin" bigint not null references public."Dim_Labor_Final" ("Id_Lab_Fin") on update cascade on delete restrict,
  estado smallint not null default 1 check (estado in (0, 1)),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

comment on table public."Dim_Labor" is 'Catálogo de labores reportadas por SCIRE asociadas a una labor final.';
comment on column public."Dim_Labor"."Lab_SCIRE" is 'Nombre de la labor de origen en SCIRE.';
comment on column public."Dim_Labor"."Id_Lab_Fin" is 'Labor final normalizada asociada a la descripción de SCIRE.';
comment on column public."Dim_Labor".estado is 'Estado del registro: 1 activo, 0 inactivo.';

create index idx_dim_labor_id_lab_fin on public."Dim_Labor" ("Id_Lab_Fin");

alter table public."Dim_Labor" enable row level security;
revoke all on table public."Dim_Labor" from public, anon, authenticated;
grant select, insert, update, delete on table public."Dim_Labor" to authenticated;

create policy dim_labor_select_admin on public."Dim_Labor"
for select to authenticated using ((select private.is_admin()));
create policy dim_labor_insert_admin on public."Dim_Labor"
for insert to authenticated with check ((select private.is_admin()));
create policy dim_labor_update_admin on public."Dim_Labor"
for update to authenticated using ((select private.is_admin())) with check ((select private.is_admin()));
create policy dim_labor_delete_admin on public."Dim_Labor"
for delete to authenticated using ((select private.is_admin()));

create or replace function private.set_dim_labor_updated_at()
returns trigger
language plpgsql
set search_path = pg_catalog
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;
revoke all on function private.set_dim_labor_updated_at() from public, anon, authenticated, service_role;

create trigger trg_dim_labor_updated_at
before update on public."Dim_Labor"
for each row execute function private.set_dim_labor_updated_at();


select setval(pg_get_serial_sequence('public."Dim_Labor"', 'Id_Lab'),
  (select max("Id_Lab") from public."Dim_Labor"), true);

do $$
declare
  v_sequence regclass := pg_get_serial_sequence('public."Dim_Labor"', 'Id_Lab');
begin
  execute format('grant usage, select on sequence %s to authenticated', v_sequence);
end;
$$;

commit;
